sys_script_include.script:
var SwiftUIActionVisibility = Class.create();
SwiftUIActionVisibility.prototype = {
    initialize: function() {},
    RefreshSwiftData_Tradeform: function(source, swiftAttribute) {

        var ghss_prop = gs.getProperty("x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss");
		var gcs_prop = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_gcs');
        var cfs_prop = gs.getProperty("x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_swift");
        if (gs.getProperty("x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_API1_active") == "true" && (source == ghss_prop || source ==gcs_prop  || ((cfs_prop.indexOf(source) > -1)))) {
            return 'true';

        } else {
            return 'false';
        }

    },
    type: 'SwiftUIActionVisibility'
};
